class TestNoteParsingAndFormatting(unittest.TestCase):
    def test_single_session_parse_and_format(self):
        raw = """Assistant-Session: 9674eda6-390f-4b1d-9910-72bec1843401
Assistant-Harness: Antigravity CLI 1.1.25
Assistant-Model: Gemini 3.8 Flash (High)
Assistant-Recorded: 2026-09-04 01:03:57 UTC

Assistant-Prompts:
  [2026-09-04 01:03:57] Make the camera pivot around the ball origin
  [2026-09-04 01:09:25]
    Let's implement this.
    Second line of prompt.
"""
        notes = gpn.parse_notes(raw)
        self.assertEqual(len(notes), 1)
        n = notes[0]
        self.assertEqual(n.session_id, "9674eda6-390f-4b1d-9910-72bec1843401")
        self.assertEqual(n.harness, "Antigravity CLI 1.1.25")
        self.assertEqual(n.model, "Gemini 3.8 Flash (High)")
        self.assertEqual(n.recorded_at, "2026-09-04 01:03:57 UTC")
        self.assertEqual(len(n.prompts), 2)
        self.assertEqual(n.prompts[0].timestamp, "2026-09-04 01:03:57")
        self.assertEqual(n.prompts[0].text, "Make the camera pivot around the ball origin")
        self.assertEqual(n.prompts[1].timestamp, "2026-09-04 01:09:25")
        self.assertIn("Second line of prompt.", n.prompts[1].text)

        # Roundtrip formatting
        formatted = gpn.serialize_notes(notes)
        self.assertIn("Assistant-Session:", formatted)
        roundtrip_notes = gpn.parse_notes(formatted)
        self.assertEqual(len(roundtrip_notes), 1)
        self.assertEqual(roundtrip_notes[0].session_id, n.session_id)
        self.assertEqual(len(roundtrip_notes[0].prompts), 2)

    def test_multi_session_parse(self):
        raw = """Assistant-Session: session-aaa
Assistant-Harness: Antigravity CLI 1.1.24
Assistant-Model: Gemini 3.8 Flash (High)
Assistant-Recorded: 2026-09-01 10:00:00 UTC

Assistant-Prompts:
  [2026-09-01 10:00:00] Initial prompt

---

Assistant-Session: session-bbb
Assistant-Harness: Antigravity CLI 1.1.25
Assistant-Model: Gemini 3.8 Flash (High)
Assistant-Recorded: 2026-09-04 01:00:00 UTC

Assistant-Prompts:
  [2026-09-04 01:00:00] Followup prompt
"""
        notes = gpn.parse_notes(raw)
        self.assertEqual(len(notes), 2)
        self.assertEqual(notes[0].session_id, "session-aaa")
        self.assertEqual(notes[1].session_id, "session-bbb")

    def test_surrounding_non_prompt_notes_preserved(self):
        raw = """Reviewed and approved by QA team.

Assistant-Session: session-xyz
Assistant-Harness: Antigravity CLI 1.1.25
Assistant-Model: Gemini 3.8 Flash (High)
Assistant-Recorded: 2026-09-04 01:00:00 UTC

Assistant-Prompts:
  [2026-09-04 01:00:00] Add camera zoom feature

Deploy-ID: 98124
"""
        prefix, block, suffix = gpn.extract_prompt_block(raw)
        self.assertEqual(prefix, "Reviewed and approved by QA team.")
        self.assertEqual(suffix, "Deploy-ID: 98124")
        self.assertIn("Assistant-Session: session-xyz", block)
        self.assertIn("Add camera zoom feature", block)

        parsed = gpn.parse_notes(raw)
        self.assertEqual(len(parsed), 1)
        self.assertEqual(parsed[0].session_id, "session-xyz")

        # Rewrapping preserves prefix and suffix
        reconstructed = gpn.wrap_prompt_block(block, prefix=prefix, suffix=suffix)
        self.assertIn("Reviewed and approved by QA team.", reconstructed)
        self.assertIn("Deploy-ID: 98124", reconstructed)


class TestNoteMerging(unittest.TestCase):
    def test_same_session_squash_merge(self):
        note1 = gpn.SessionNote(
            session_id="session-1",
            harness="Antigravity CLI 1.1.25",
            model="Gemini 3.8 Flash (High)",
            recorded_at="2026-09-04 01:05:00 UTC",
            prompts=[
                gpn.PromptEntry("2026-09-04 01:03:57", "First prompt"),
            ],
        )
        note2 = gpn.SessionNote(
            session_id="session-1",
            harness="Antigravity CLI 1.1.25",
            model="Gemini 3.8 Flash (High)",
            recorded_at="2026-09-04 01:10:00 UTC",
            prompts=[
                gpn.PromptEntry("2026-09-04 01:03:57", "First prompt"),  # Duplicate
                gpn.PromptEntry("2026-09-04 01:09:25", "Second prompt"),
            ],
        )

        merged = gpn.merge_session_notes([note1, note2])
        self.assertEqual(len(merged), 1)
        m = merged[0]
        self.assertEqual(m.session_id, "session-1")
        self.assertEqual(m.recorded_at, "2026-09-04 01:10:00 UTC")  # Latest timestamp
        self.assertEqual(len(m.prompts), 2)
        self.assertEqual(m.prompts[0].text, "Second prompt")
        self.assertEqual(m.prompts[1].text, "First prompt")

    def test_cross_session_squash_merge(self):
        note1 = gpn.SessionNote(
            session_id="session-day-1",
            harness="Antigravity CLI 1.1.24",
            model="Gemini 3.8 Flash (High)",
            recorded_at="2026-09-01 10:00:00 UTC",
            prompts=[
                gpn.PromptEntry("2026-09-01 09:50:00", "Prompt from day 1"),
            ],
        )
        note2 = gpn.SessionNote(
            session_id="session-day-2",
            harness="Antigravity CLI 1.1.25",
            model="Gemini 3.8 Flash (High)",
            recorded_at="2026-09-04 01:10:00 UTC",
            prompts=[
                gpn.PromptEntry("2026-09-04 01:09:25", "Prompt from day 2"),
            ],
        )

        merged = gpn.merge_session_notes([note1, note2])
        self.assertEqual(len(merged), 2)
        self.assertEqual(merged[0].session_id, "session-day-1")
        self.assertEqual(merged[1].session_id, "session-day-2")

        serialized = gpn.serialize_notes(merged)
        self.assertIn("Assistant-Session: session-day-1", serialized)
        self.assertIn("Assistant-Session: session-day-2", serialized)
        self.assertIn("\n\n---\n\n", serialized)


class TestGitPostRewriteIntegration(unittest.TestCase):
    def setUp(self):
        self.tmp_dir = tempfile.mkdtemp()
        self.repo_dir = Path(self.tmp_dir)

        # Initialize git repo
        subprocess.run(["git", "init"], cwd=self.repo_dir, check=True, capture_output=True)
        subprocess.run(["git", "config", "user.name", "Test User"], cwd=self.repo_dir, check=True)
        subprocess.run(["git", "config", "user.email", "test@example.com"], cwd=self.repo_dir, check=True)

    def tearDown(self):
        shutil.rmtree(self.tmp_dir)

    def _commit(self, filename: str, content: str, msg: str) -> str:
        fpath = self.repo_dir / filename
        fpath.write_text(content)
        subprocess.run(["git", "add", filename], cwd=self.repo_dir, check=True, capture_output=True)
        subprocess.run(["git", "commit", "-m", msg], cwd=self.repo_dir, check=True, capture_output=True)
        out = subprocess.check_output(["git", "rev-parse", "HEAD"], cwd=self.repo_dir, text=True).strip()
        return out

    def test_post_rewrite_squash(self):
        sha1 = self._commit("file1.txt", "hello", "Commit 1")
        sha2 = self._commit("file2.txt", "world", "Commit 2")

        # Attach prompt notes to sha1 and sha2
        note1 = gpn.SessionNote(
            session_id="session-test",
            harness="Antigravity CLI 1.1.25",
            model="Gemini 3.8 Flash (High)",
            recorded_at="2026-09-04 01:05:00 UTC",
            prompts=[gpn.PromptEntry("2026-09-04 01:03:00", "Create file 1")],
        )
        note2 = gpn.SessionNote(
            session_id="session-test",
            harness="Antigravity CLI 1.1.25",
            model="Gemini 3.8 Flash (High)",
            recorded_at="2026-09-04 01:10:00 UTC",
            prompts=[gpn.PromptEntry("2026-09-04 01:08:00", "Create file 2")],
        )
        gpn.write_note_content(sha1, note1.format(), repo_root=self.repo_dir)
        gpn.write_note_content(sha2, note2.format(), repo_root=self.repo_dir)

        # Simulate a squash into sha3
        sha3 = self._commit("file3.txt", "squashed", "Squashed Commit")

        # Simulate git post-rewrite stdin:
        # <sha1> <sha3>
        # <sha2> <sha3>
        stdin_data = f"{sha1} {sha3}\n{sha2} {sha3}\n"

        script_path = Path(gpn.__file__).resolve()
        res = subprocess.run(
            ["python3", str(script_path), "post-rewrite"],
            cwd=self.repo_dir,
            input=stdin_data,
            text=True,
            capture_output=True,
        )
        self.assertEqual(res.returncode, 0)

        # Verify sha3 has the merged note
        note_sha3_raw = gpn.get_note_content(sha3, repo_root=self.repo_dir)
        self.assertIsNotNone(note_sha3_raw)
        parsed = gpn.parse_notes(note_sha3_raw)
        self.assertEqual(len(parsed), 1)
        self.assertEqual(parsed[0].session_id, "session-test")
        self.assertEqual(len(parsed[0].prompts), 2)
        self.assertEqual(parsed[0].prompts[0].text, "Create file 2")
        self.assertEqual(parsed[0].prompts[1].text, "Create file 1")

    def test_init_installs_hooks_by_default(self):
        script_path = Path(gpn.__file__).resolve()
        res = subprocess.run(
            ["python3", str(script_path), "init"],
            cwd=self.repo_dir,
            capture_output=True,
            text=True,
        )
        self.assertEqual(res.returncode, 0)

        hooks_dir = self.repo_dir / ".git" / "hooks"
        self.assertTrue((hooks_dir / "post-rewrite").exists())
        self.assertTrue(os.access(hooks_dir / "post-rewrite", os.X_OK))
        # post-commit is installed by default
        self.assertTrue((hooks_dir / "post-commit").exists())
        self.assertTrue(os.access(hooks_dir / "post-commit", os.X_OK))

        # Skill is not installed by default
        skill_file = self.repo_dir / ".agents" / "skills" / "git-prompt-log" / "SKILL.md"
        self.assertFalse(skill_file.exists())

    def test_init_no_post_commit(self):
        script_path = Path(gpn.__file__).resolve()
        res = subprocess.run(
            ["python3", str(script_path), "init", "--no-post-commit"],
            cwd=self.repo_dir,
            capture_output=True,
            text=True,
        )
        self.assertEqual(res.returncode, 0)

        hooks_dir = self.repo_dir / ".git" / "hooks"
        self.assertTrue((hooks_dir / "post-rewrite").exists())
        self.assertFalse((hooks_dir / "post-commit").exists())

    def test_init_subcommand_defaults_to_no_skill(self):
        script_path = Path(gpn.__file__).resolve()
