class TestPromptExclusionAndRetraction(unittest.TestCase):
    def setUp(self):
        self.temp_dir = tempfile.TemporaryDirectory()
        self.logs_dir = Path(self.temp_dir.name) / "brain" / "test-session-uuid" / ".system_generated" / "logs"
        self.logs_dir.mkdir(parents=True, exist_ok=True)
        self.transcript_file = self.logs_dir / "transcript.jsonl"

    def tearDown(self):
        self.temp_dir.cleanup()

    def _write_transcript(self, user_prompts: list):
        with open(self.transcript_file, "w", encoding="utf-8") as f:
            for i, p in enumerate(user_prompts):
                step = {
                    "type": "USER_INPUT",
                    "source": "USER_EXPLICIT",
                    "content": p,
                    "created_at": f"2026-09-04T09:{10+i:02d}:00Z",
                }
                f.write(json.dumps(step) + "\n")

    def test_prompts_with_bracketed_text_preserved_verbatim(self):
        self._write_transcript([
            "First valid prompt",
            "[ignore] What was that command again?",
            "[skip] Run tests",
            "[retract] Fix camera",
            "Second valid prompt",
        ])
        data = gpn.parse_session_transcript(self.transcript_file)
        self.assertIsNotNone(data)
        prompts = [p.text for p in data["prompts"]]
        self.assertEqual(prompts, [
            "First valid prompt",
            "[ignore] What was that command again?",
            "[skip] Run tests",
            "[retract] Fix camera",
            "Second valid prompt",
        ])

    def test_normal_english_sentences_preserved(self):
        self._write_transcript([
            "Ignore previous compiler warnings and proceed with build",
        ])
        data = gpn.parse_session_transcript(self.transcript_file)
        self.assertIsNotNone(data)
        prompts = [p.text for p in data["prompts"]]
        self.assertEqual(prompts, ["Ignore previous compiler warnings and proceed with build"])



class TestWorkflowAndAttributionLifecycle(unittest.TestCase):
    def setUp(self):
        self.tmp_dir = tempfile.TemporaryDirectory()
        self.repo_dir = Path(self.tmp_dir.name) / "repo"
        self.repo_dir.mkdir()
        self.data_dir = Path(self.tmp_dir.name) / "data"
        self.data_dir.mkdir()

        # Set up git repo
        subprocess.run(["git", "init", "-b", "main"], cwd=self.repo_dir, check=True, capture_output=True)
        subprocess.run(["git", "config", "user.name", "Test User"], cwd=self.repo_dir, check=True)
        subprocess.run(["git", "config", "user.email", "test@example.com"], cwd=self.repo_dir, check=True)

        # Initialize git-prompt-log hooks
        script_path = Path(gpn.__file__).resolve()
        subprocess.run(["python3", str(script_path), "init"], cwd=self.repo_dir, check=True, capture_output=True)

        # Set up mock transcript
        self.session_id = "test-workflow-session-1234"
        self.logs_dir = self.data_dir / "brain" / self.session_id / ".system_generated" / "logs"
        self.logs_dir.mkdir(parents=True, exist_ok=True)
        self.transcript_file = self.logs_dir / "transcript.jsonl"

        # Prepare env with local bin directory at the head of PATH
        self.env = os.environ.copy()
        self.env["PATH"] = f"{bin_path.parent}:{self.env.get('PATH', '')}"
        self.env["ANTIGRAVITY_DATA_DIR"] = str(self.data_dir)
        self.env["ANTIGRAVITY_CONVERSATION_ID"] = self.session_id

    def tearDown(self):
        self.tmp_dir.cleanup()

    def _append_prompt(self, text: str, timestamp_str: str):
        step = {
            "type": "USER_INPUT",
            "source": "USER_EXPLICIT",
            "content": text,
            "created_at": timestamp_str,
        }
        with open(self.transcript_file, "a", encoding="utf-8") as f:
            f.write(json.dumps(step) + "\n")

    def _commit(self, filename: str, content: str, msg: str) -> str:
        fpath = self.repo_dir / filename
        fpath.write_text(content)
        subprocess.run(["git", "add", filename], cwd=self.repo_dir, check=True, capture_output=True, env=self.env)
        subprocess.run(["git", "commit", "-m", msg], cwd=self.repo_dir, check=True, capture_output=True, env=self.env)
        return subprocess.check_output(["git", "rev-parse", "HEAD"], cwd=self.repo_dir, text=True, env=self.env).strip()

    def test_sequential_commits_cumulative_history(self):
        # 1. First prompt and commit
        self._append_prompt("Implement feature part 1", "2026-09-04T10:00:00Z")
        sha1 = self._commit("file1.txt", "v1", "feat: Feature part 1")

        note1_raw = gpn.get_note_content(sha1, repo_root=self.repo_dir)
        self.assertIsNotNone(note1_raw)
        notes1 = gpn.parse_notes(note1_raw)
        self.assertEqual(len(notes1), 1)
        self.assertEqual(len(notes1[0].prompts), 1)
        self.assertEqual(notes1[0].prompts[0].text, "Implement feature part 1")

        # 2. Second prompt and commit
        self._append_prompt("Implement feature part 2", "2026-09-04T10:05:00Z")
        sha2 = self._commit("file2.txt", "v2", "feat: Feature part 2")

        # Commit 2 carries full cumulative history (Prompt 1 + Prompt 2)
        note2_raw = gpn.get_note_content(sha2, repo_root=self.repo_dir)
        self.assertIsNotNone(note2_raw)
        notes2 = gpn.parse_notes(note2_raw)
        # Commit 2 carries full cumulative history (Prompt 2 causal at top, Prompt 1 below)
        note2_raw = gpn.get_note_content(sha2, repo_root=self.repo_dir)
        self.assertIsNotNone(note2_raw)
        notes2 = gpn.parse_notes(note2_raw)
        self.assertEqual(len(notes2), 1)
        self.assertEqual(len(notes2[0].prompts), 2)
        self.assertEqual(notes2[0].prompts[0].text, "Implement feature part 2")
        self.assertEqual(notes2[0].prompts[1].text, "Implement feature part 1")

        # Commit 1 still retains its original snapshot
        note1_check = gpn.get_note_content(sha1, repo_root=self.repo_dir)
        self.assertEqual(note1_check, note1_raw)

        # Verify show --active and show --incremental
        out_active = subprocess.check_output(
            ["python3", str(Path(gpn.__file__).resolve()), "show", "--active", sha2],
            cwd=self.repo_dir,
            text=True,
            env=self.env,
        ).strip()
        self.assertEqual(out_active, "[2026-09-04 10:05:00 UTC] Implement feature part 2")

        out_inc = subprocess.check_output(
            ["python3", str(Path(gpn.__file__).resolve()), "show", "--incremental", sha2],
            cwd=self.repo_dir,
            text=True,
            env=self.env,
        ).strip()
        self.assertEqual(out_inc, "[2026-09-04 10:05:00 UTC] Implement feature part 2")

    def test_commit_amend_carries_and_merges_note(self):
        self._append_prompt("Initial commit prompt", "2026-09-04T10:00:00Z")
        sha1 = self._commit("file1.txt", "v1", "feat: Original")

        # Now add a followup prompt before amending
        self._append_prompt("Improve performance on feature", "2026-09-04T10:05:00Z")
        fpath = self.repo_dir / "file1.txt"
        fpath.write_text("v2")
        subprocess.run(["git", "add", "file1.txt"], cwd=self.repo_dir, check=True, env=self.env)
        subprocess.run(["git", "commit", "--amend", "-m", "feat: Original improved"], cwd=self.repo_dir, check=True, env=self.env)

        sha_amended = subprocess.check_output(["git", "rev-parse", "HEAD"], cwd=self.repo_dir, text=True).strip()
        self.assertNotEqual(sha1, sha_amended)

        note_amended_raw = gpn.get_note_content(sha_amended, repo_root=self.repo_dir)
        self.assertIsNotNone(note_amended_raw)
        notes = gpn.parse_notes(note_amended_raw)
        self.assertEqual(len(notes), 1)
        self.assertEqual(len(notes[0].prompts), 2)
        self.assertEqual(notes[0].prompts[0].text, "Improve performance on feature")
        self.assertEqual(notes[0].prompts[1].text, "Initial commit prompt")

    def test_native_git_rebase_squash(self):
        # Base commit
        self._commit("base.txt", "base", "chore: Base commit")

        # Commit 1
        self._append_prompt("Build part A", "2026-09-04T10:00:00Z")
        sha1 = self._commit("a.txt", "a", "feat: Part A")

        # Commit 2
        self._append_prompt("Build part B", "2026-09-04T10:05:00Z")
        sha2 = self._commit("b.txt", "b", "feat: Part B")

        # Interactive squash of HEAD into HEAD~1
        # Set GIT_SEQUENCE_EDITOR to change 2nd 'pick' to 'squash'
        py_editor = "python3 -c 'import sys; p=sys.argv[1]; lines=open(p).readlines(); lines[1]=\"squash \" + lines[1].split(\" \", 1)[1]; open(p,\"w\").writelines(lines)'"
        env = self.env.copy()
        env["GIT_SEQUENCE_EDITOR"] = py_editor
        env["GIT_EDITOR"] = "true"  # for commit message editor
        subprocess.run(["git", "rebase", "-i", "HEAD~2"], cwd=self.repo_dir, check=True, env=env)

        sha_squashed = subprocess.check_output(["git", "rev-parse", "HEAD"], cwd=self.repo_dir, text=True).strip()
        note_raw = gpn.get_note_content(sha_squashed, repo_root=self.repo_dir)
        self.assertIsNotNone(note_raw)
        notes = gpn.parse_notes(note_raw)
        self.assertEqual(len(notes), 1)
        self.assertEqual(len(notes[0].prompts), 2)
        self.assertEqual(notes[0].prompts[0].text, "Build part B")
        self.assertEqual(notes[0].prompts[1].text, "Build part A")

    def test_native_git_rebase_onto_upstream(self):
        # Base commit
        self._append_prompt("Base commit", "2026-09-04T09:50:00Z")
        sha_base = self._commit("base.txt", "base", "chore: Base")

        # Feature branch
        subprocess.run(["git", "checkout", "-b", "feature"], cwd=self.repo_dir, check=True, env=self.env)
        self._append_prompt("Feature work", "2026-09-04T10:00:00Z")
        sha_feat = self._commit("feat.txt", "feat", "feat: Feature")

        # Switch to main and add upstream commit
        subprocess.run(["git", "checkout", "main"], cwd=self.repo_dir, check=True, env=self.env)
        self._append_prompt("Upstream work", "2026-09-04T10:05:00Z")
        sha_upstream = self._commit("upstream.txt", "upstream", "chore: Upstream")

        # Switch back to feature and rebase onto main
        subprocess.run(["git", "checkout", "feature"], cwd=self.repo_dir, check=True, env=self.env)
        subprocess.run(["git", "rebase", "main"], cwd=self.repo_dir, check=True, env=self.env)

        # Rebased feature commit should have a new hash but retain its prompt note!
        sha_rebased = subprocess.check_output(["git", "rev-parse", "HEAD"], cwd=self.repo_dir, text=True).strip()
        self.assertNotEqual(sha_feat, sha_rebased)

        note_raw = gpn.get_note_content(sha_rebased, repo_root=self.repo_dir)
        self.assertIsNotNone(note_raw)
        notes = gpn.parse_notes(note_raw)
        self.assertEqual(len(notes[0].prompts), 2)
        self.assertEqual(notes[0].prompts[0].text, "Feature work")
        self.assertEqual(notes[0].prompts[1].text, "Base commit")

    def test_rebase_drop_narrative_lands_on_replacement_commit(self):
        # 1. Base commit
        self._commit("base.txt", "base", "chore: Base commit")

        # 2. First feature commit
        self._append_prompt("Implement basic audio engine", "2026-09-04T10:05:00Z")
        sha1 = self._commit("audio.c", "audio", "audio: Implement basic audio engine")

        # 3. Dead-end feature commit
        self._append_prompt("Try implementing custom Doppler shift calculation in audio update loop", "2026-09-04T10:10:00Z")
        sha2_dead_end = self._commit("doppler.c", "doppler", "audio: Add custom Doppler calculation")

        # 4. User redirects: drop Doppler commit
        self._append_prompt("The custom Doppler math is causing distortion. Drop that commit and use OpenAL distance attenuation instead", "2026-09-04T10:15:00Z")

        # Drop sha2 via interactive rebase
        drop_py = "python3 -c 'import sys; p=sys.argv[1]; lines=open(p).readlines(); lines[1]=\"drop \" + lines[1].split(\" \", 1)[1]; open(p,\"w\").writelines(lines)'"
        env = self.env.copy()
        env["GIT_SEQUENCE_EDITOR"] = drop_py
        subprocess.run(["git", "rebase", "-i", "HEAD~2"], cwd=self.repo_dir, check=True, env=env)

        # 5. Replacement commit authored
        sha3 = self._commit("openal.c", "openal", "audio: Configure OpenAL distance attenuation")

        # Verify sha1 has ONLY prompt 1
        note1_raw = gpn.get_note_content(sha1, repo_root=self.repo_dir)
        notes1 = gpn.parse_notes(note1_raw)
        self.assertEqual(len(notes1[0].prompts), 1)
        self.assertEqual(notes1[0].prompts[0].text, "Implement basic audio engine")

        # Replacement commit sha3 retains full cumulative lineage with newest causal prompt at top!
        note3_raw = gpn.get_note_content(sha3, repo_root=self.repo_dir)
        self.assertIsNotNone(note3_raw)
        notes3 = gpn.parse_notes(note3_raw)
        self.assertEqual(len(notes3[0].prompts), 3)
        self.assertEqual(notes3[0].prompts[0].text, "The custom Doppler math is causing distortion. Drop that commit and use OpenAL distance attenuation instead")
        self.assertEqual(notes3[0].prompts[1].text, "Try implementing custom Doppler shift calculation in audio update loop")
        self.assertEqual(notes3[0].prompts[2].text, "Implement basic audio engine")

    def test_rebase_reorder_commits_preserves_notes_without_duplication(self):
        # 1. Base commit
        self._commit("base.txt", "base", "chore: Base")

        # 2. Commit A
        self._append_prompt("Feature A (Sound)", "2026-09-04T10:05:00Z")
        sha_a = self._commit("sound.txt", "sound", "feat: Sound")

        # 3. Commit B
        self._append_prompt("Feature B (Music)", "2026-09-04T10:10:00Z")
        sha_b = self._commit("music.txt", "music", "feat: Music")

        # Reorder commits so B is applied before A
        reorder_py = "python3 -c 'import sys; p=sys.argv[1]; lines=open(p).readlines(); lines[0], lines[1] = lines[1], lines[0]; open(p,\"w\").writelines(lines)'"
        env = self.env.copy()
        env["GIT_SEQUENCE_EDITOR"] = reorder_py
        subprocess.run(["git", "rebase", "-i", "HEAD~2"], cwd=self.repo_dir, check=True, env=env)

        # Retrieve new commit hashes in reordered history (HEAD is A, HEAD~1 is B)
        new_sha_a = subprocess.check_output(["git", "rev-parse", "HEAD"], cwd=self.repo_dir, text=True).strip()
        new_sha_b = subprocess.check_output(["git", "rev-parse", "HEAD~1"], cwd=self.repo_dir, text=True).strip()

        # Both reordered commits retain their respective notes
        note_a = gpn.parse_notes(gpn.get_note_content(new_sha_a, repo_root=self.repo_dir))[0]
        note_b = gpn.parse_notes(gpn.get_note_content(new_sha_b, repo_root=self.repo_dir))[0]
        self.assertEqual(len(note_a.prompts), 1)
        self.assertEqual(note_a.prompts[0].text, "Feature A (Sound)")
        self.assertEqual(len(note_b.prompts), 2)
        self.assertEqual(note_b.prompts[0].text, "Feature B (Music)")
        self.assertEqual(note_b.prompts[1].text, "Feature A (Sound)")

        # 4. Author a subsequent commit C in the same session
        self._append_prompt("Feature C (UI)", "2026-09-04T10:15:00Z")
        sha_c = self._commit("ui.txt", "ui", "feat: UI")

        # Commit C receives all prompts up to its creation (newest causal at top)
        note_c = gpn.parse_notes(gpn.get_note_content(sha_c, repo_root=self.repo_dir))[0]
        self.assertEqual(len(note_c.prompts), 3)
        self.assertEqual(note_c.prompts[0].text, "Feature C (UI)")

    def test_git_reset_recommit_preserves_cumulative_history(self):
        # 1. Base commit
        self._commit("base.txt", "base", "chore: Base commit")

        # 2. Turn 1
        self._append_prompt("First attempt at parser", "2026-09-04T10:00:00Z")
        sha1 = self._commit("p.txt", "parser", "feat: Parser")

        # 3. Turn 2
        self._append_prompt("First attempt at AST", "2026-09-04T10:05:00Z")
        sha2 = self._commit("a.txt", "ast", "feat: AST")

        # 4. Turn 3: Agent does a hard/soft reset to clean up and re-split
        self._append_prompt("Reset and re-split cleanly into tokens and parser", "2026-09-04T10:10:00Z")
        subprocess.run(["git", "reset", "--soft", "HEAD~2"], cwd=self.repo_dir, check=True)

        # Author replacement commits
        sha_new1 = self._commit("tokens.txt", "tokens", "feat: Tokens")
        sha_new2 = self._commit("parser.txt", "parser_clean", "feat: Clean Parser")

        # Both replacement commits must preserve the full session history with causal prompt at top!
        note_new1 = gpn.parse_notes(gpn.get_note_content(sha_new1, repo_root=self.repo_dir))[0]
        note_new2 = gpn.parse_notes(gpn.get_note_content(sha_new2, repo_root=self.repo_dir))[0]

        self.assertEqual(len(note_new1.prompts), 3)
        self.assertEqual(note_new1.prompts[0].text, "Reset and re-split cleanly into tokens and parser")
        self.assertEqual(note_new1.prompts[1].text, "First attempt at AST")
        self.assertEqual(note_new1.prompts[2].text, "First attempt at parser")

        self.assertEqual(len(note_new2.prompts), 3)
        self.assertEqual(note_new2.prompts[0].text, "Reset and re-split cleanly into tokens and parser")

        # Log command displays cleanly
        out_log = subprocess.check_output(
            ["python3", str(Path(gpn.__file__).resolve()), "log", "--no-pager"],
            cwd=self.repo_dir,
            text=True,
            env=self.env,
        )
        self.assertIn("feat: Clean Parser", out_log)
        self.assertIn("Reset and re-split cleanly into tokens and parser", out_log)

        # Verify color formatting in log
        out_color = subprocess.check_output(
            ["python3", str(Path(gpn.__file__).resolve()), "log", "--color=always", "--no-pager"],
            cwd=self.repo_dir,
            text=True,
            env=self.env,
        )
        self.assertIn("\033[33m", out_color)
        self.assertIn("\033[36m", out_color)
        self.assertIn("\033[0m", out_color)

        out_no_color = subprocess.check_output(
            ["python3", str(Path(gpn.__file__).resolve()), "log", "--color=never", "--no-pager"],
            cwd=self.repo_dir,
            text=True,
            env=self.env,
        )
        self.assertNotIn("\033[33m", out_no_color)
        self.assertNotIn("\033[36m", out_no_color)

