    def test_post_commit_causality_guard_and_claude_hook(self):
        repo_dir = self.work_dir / "repo_claude"
        repo_dir.mkdir()
        subprocess.run(["git", "init", "-b", "main"], cwd=repo_dir, check=True, capture_output=True)
