    def test_plain_invocation_defaults_to_log(self):
        repo_dir = self.work_dir / "repo_plain_log"
        repo_dir.mkdir()
        subprocess.run(["git", "init", "-b", "main"], cwd=repo_dir, check=True, capture_output=True)
        subprocess.run(["git", "config", "user.name", "Test User"], cwd=repo_dir, check=True)
        subprocess.run(["git", "config", "user.email", "test@example.com"], cwd=repo_dir, check=True)

        f = repo_dir / "hello.txt"
        f.write_text("hello world")
        subprocess.run(["git", "add", "hello.txt"], cwd=repo_dir, check=True)
        subprocess.run(["git", "commit", "-m", "feat: initial commit"], cwd=repo_dir, check=True)

        script_path = str(bin_path)

        # Attach a prompt note
        cmd_rec = [
            "python3",
            script_path,
            "record",
            "-m",
            "Initial prompt steering",
            "-c",
            "HEAD",
        ]
        subprocess.run(cmd_rec, cwd=repo_dir, check=True, capture_output=True)

        # 1. Run plain git-prompt-log
        res_plain = subprocess.run(
            ["python3", script_path, "--no-pager"],
            cwd=repo_dir,
            capture_output=True,
            text=True,
            check=True,
        )

        # 2. Run explicit git-prompt-log log
        res_log = subprocess.run(
            ["python3", script_path, "log", "--no-pager"],
            cwd=repo_dir,
            capture_output=True,
            text=True,
            check=True,
        )

        # Plain git-prompt-log must match git-prompt-log log output exactly
        self.assertEqual(res_plain.returncode, 0)
        self.assertEqual(res_log.returncode, 0)
        self.assertEqual(res_plain.stdout, res_log.stdout)
        self.assertIn("feat: initial commit", res_plain.stdout)
        self.assertIn("Initial prompt steering", res_plain.stdout)

        # 3. Verify --help still shows top-level help with default indication
        res_help = subprocess.run(
            ["python3", script_path, "--help"],
            cwd=repo_dir,
            capture_output=True,
            text=True,
            check=True,
        )
        self.assertIn("Display commits with their steering prompts (default)", res_help.stdout)

        # 4. Verify invalid command still produces error
        res_invalid = subprocess.run(
            ["python3", script_path, "unknown-cmd"],
            cwd=repo_dir,
            capture_output=True,
            text=True,
        )
        self.assertEqual(res_invalid.returncode, 2)

    def test_log_placeholder_when_no_prompts(self):
        repo_dir = self.work_dir / "repo_log_placeholder"
        repo_dir.mkdir()
        subprocess.run(["git", "init", "-b", "main"], cwd=repo_dir, check=True, capture_output=True)
        subprocess.run(["git", "config", "user.name", "Test User"], cwd=repo_dir, check=True)
        subprocess.run(["git", "config", "user.email", "test@example.com"], cwd=repo_dir, check=True)

        script_path = str(bin_path)

        # Commit 1: No prompts recorded
        f1 = repo_dir / "file1.txt"
        f1.write_text("file1 content")
        subprocess.run(["git", "add", "file1.txt"], cwd=repo_dir, check=True)
        subprocess.run(["git", "commit", "-m", "chore: unprompted commit"], cwd=repo_dir, check=True)

        # Commit 2: With prompt note
        f2 = repo_dir / "file2.txt"
        f2.write_text("file2 content")
        subprocess.run(["git", "add", "file2.txt"], cwd=repo_dir, check=True)
        subprocess.run(["git", "commit", "-m", "feat: prompted commit"], cwd=repo_dir, check=True)
        subprocess.run(
            ["python3", script_path, "record", "-m", "Steering prompt for commit 2", "-c", "HEAD"],
            cwd=repo_dir,
            check=True,
            capture_output=True,
        )

        res_log = subprocess.run(
            ["python3", script_path, "log", "--no-pager"],
            cwd=repo_dir,
            capture_output=True,
            text=True,
            check=True,
        )

        self.assertIn("feat: prompted commit", res_log.stdout)
        self.assertIn("Steering prompt for commit 2", res_log.stdout)
        self.assertIn("chore: unprompted commit", res_log.stdout)
        self.assertIn("no prompts recorded", res_log.stdout)

        # Check structure: unprompted commit has placeholder right below it
        lines = res_log.stdout.splitlines()
        found_unprompted = False
        found_placeholder = False
        for i, line in enumerate(lines):
            if "chore: unprompted commit" in line:
                found_unprompted = True
                self.assertEqual(lines[i + 1].strip(), "no prompts recorded")
                found_placeholder = True
                break
        self.assertTrue(found_unprompted)
        self.assertTrue(found_placeholder)

    def test_worktree_session_detection(self):
        # 1. Setup main repository
        main_repo = self.work_dir / "main_repo"
        main_repo.mkdir()
        subprocess.run(["git", "init", "-b", "main"], cwd=main_repo, check=True, capture_output=True)
        subprocess.run(["git", "config", "user.name", "Test User"], cwd=main_repo, check=True)
        subprocess.run(["git", "config", "user.email", "test@example.com"], cwd=main_repo, check=True)
        (main_repo / "main_file.txt").write_text("main file")
        subprocess.run(["git", "add", "."], cwd=main_repo, check=True)
        subprocess.run(["git", "commit", "-m", "chore: initial commit on main"], cwd=main_repo, check=True)

        # 2. Create a nested worktree at .worktrees/feature-wt
        wt_dir = main_repo / ".worktrees" / "feature-wt"
        subprocess.run(["git", "worktree", "add", "-b", "feature", str(wt_dir)], cwd=main_repo, check=True, capture_output=True)

        # 3. Create mock Antigravity transcript referencing main_repo path (session opened in main repo)
        brain_dir = self.work_dir / "brain"
        session_id = "sess-worktree-test-1234"
        t_dir = brain_dir / session_id / ".system_generated" / "logs"
        t_dir.mkdir(parents=True, exist_ok=True)
        transcript = t_dir / "transcript.jsonl"
        lines = [
            json.dumps({
                "step_index": 1,
                "source": "USER_EXPLICIT",
                "type": "USER_INPUT",
                "created_at": "2026-09-04T12:00:00Z",
                "content": f"<USER_REQUEST>Work in {main_repo} on feature</USER_REQUEST>",
            }),
            json.dumps({
                "step_index": 2,
                "source": "MODEL",
                "type": "PLANNER_RESPONSE",
                "created_at": "2026-09-04T12:01:00Z",
                "content": "Done.",
            }),
        ]
        transcript.write_text("\n".join(lines), encoding="utf-8")

        adapter = gpn.AntigravityAdapter()

        # Verify get_repo_identifiers resolves both worktree and main repo
        wt_identifiers = gpn.get_repo_identifiers(repo_root=wt_dir)
        self.assertIn(str(wt_dir).lower(), wt_identifiers)
        self.assertIn(wt_dir.name.lower(), wt_identifiers)
        self.assertIn(str(main_repo).lower(), wt_identifiers)
        self.assertIn(main_repo.name.lower(), wt_identifiers)

        # Verify AntigravityAdapter resolves main_repo session from inside worktree
        orig_get_brain = gpn.get_brain_dir
        gpn.get_brain_dir = lambda: brain_dir
        orig_env = os.environ.copy()
        os.environ.pop("AGY_SESSION_ID", None)
        os.environ.pop("ANTIGRAVITY_CONVERSATION_ID", None)
        try:
            detected_sid = adapter.detect_session_id(repo_root=wt_dir)
            self.assertEqual(detected_sid, session_id)

            session_data = adapter.find_session_data(repo_root=wt_dir)
            self.assertIsNotNone(session_data)
            self.assertEqual(session_data["session_id"], session_id)
            self.assertEqual(len(session_data["prompts"]), 1)
            self.assertIn("feature", session_data["prompts"][0].text)
        finally:
            gpn.get_brain_dir = orig_get_brain
            os.environ.clear()
            os.environ.update(orig_env)

        # Verify ClaudeCodeAdapter resolves main_repo .claude directory from inside worktree
        (main_repo / ".claude").mkdir(parents=True, exist_ok=True)
        claude_adapter = gpn.ClaudeCodeAdapter()
        claude_dirs = claude_adapter._get_claude_dirs(repo_root=wt_dir)
        self.assertIn(main_repo / ".claude", claude_dirs)


